    let n: usize = input.trim().parse().expect("Please enter a valid number");

    let mut phone = String::new();
    io::stdin().read_line(&mut phone)?;
    let phone = phone.trim();

    if n < 2 {
        writeln!(io::stdout(), "{}", phone)?;
        return Ok(());
    }

    let mut idx = 2;
    let mut n = n - 2;

    print!("{}{}", phone.chars().nth(0).unwrap(), phone.chars().nth(1).unwrap());

    if n % 2 == 1 {
        print!("{}", phone.chars().nth(2).unwrap());
        idx += 1;
        n -= 1;
    }

    let groups_num = n / 2;

    for _ in 0..groups_num {
        print!("-");
        for j in idx..idx + 2 {
            print!("{}", phone.chars().nth(j).unwrap());
        }
