		for (j = i + 1; j <= n && (min == INT_MAX || j <= i + min); j++) {
			if (j < n) {
				int c = s[j] - 'a';

				if (min > aa[c])
					min = aa[c];
			}
			if (max < j - i)
				max = j - i;
			dp[j] = (dp[j] + dp[i]) % MOD;
		}
	}
	cnt = 0;
	for (i = 0; i < n; ) {
		int min = aa[s[i] - 'a'];

		j = i;
		while (j < n && j < i + min) {
			if (j + 1 < n) {
				int c = s[j + 1] - 'a';

				if (min > aa[c])
					min = aa[c];
			}
			j++;
		}
