        if p <= n[0] {
            n[1] = n[2];
            n[0] -= p;
        } else {
            n[1] += n[0];
            n[0] = 0;
        }

        if n[0] > 0 {
            let half = n[0] / 2;
            n[1] += half;
            n[2] += half;
            if n[0] % 2 != 0 {
                n[1] += 1;
            }
        }

        let s = n[1].min(n[2]);
        println!("{}", s);
    }
}

