use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    while let Some(Ok(row_str)) = lines.next() {
        let row: usize = row_str.parse().unwrap();
        let mut grid = vec![vec![' '; row]; row];

        for i in 0..row {
            if let Some(Ok(line)) = lines.next() {
                grid[i] = line.chars().collect();
            }
        }

        for j in 1..row - 1 {
            for k in 1..row - 1 {
                if grid[j][k] == '#' {
                    if grid[j - 1][k] == '#' && grid[j][k - 1] == '#' && grid[j + 1][k] == '#' && grid[j][k + 1] == '#' {
                        grid[j][k] = '.';
                        grid[j - 1][k] = '.';
                        grid[j][k - 1] = '.';
                        grid[j + 1][k] = '.';
                        grid[j][k + 1] = '.';
                    }
                }
            }
        }

        let mut flag = false;
        for row in &grid {
            for &cell in row {
                if cell != '.' {
                    flag = true;
                    break;
                }
            }
            if flag {
                break;
            }
        }

        if flag {
            println!("NO");
        } else {
            println!("YES");
        }
    }
}

