            *b_char = match (*b_char, *a_char) {
                ('?', _) => *a_char,
                (_, '?') => *b_char,
                (b_char, a_char) if b_char != a_char => 'A',
                _ => *b_char,
            };
        }
    }

    for c in b {
        match c {
            'A' => print!("?"),
            '?' => print!("x"),
            _ => print!("{}", c),
        }
    }
    Ok(())
