      ++b[i - 1];
    }
  }
  long long ans = 0;
  int last = -1;
  for (i = N - 1; i > 0; --i) {
    if (cnt[i] == 0) continue;
    if (last != -1) {
      --cnt[i];
      ans += (long long) last * i;
      last = -1;
    }
    ans += (long long) cnt[i] / 2 * i * i;
    if (cnt[i] % 2 == 1) {
      last = i;
    }
  }
  printf("%I64d\n", ans);
  return 0;
}

