        sum += match gap {
            x if x <= t1 => p1 * x,
            x if x <= t1 + t2 => p1 * t1 + p2 * (x - t1),
            _ => p1 * t1 + p2 * t2 + p3 * (gap - t1 - t2),
        };
    }

