    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let d: usize = parts.next().unwrap().parse().unwrap();

    let mut gem = vec![0; 30001];
    for _ in 0..n {
        let mut input = String::new();
        std::io::stdin().read_line(&mut input).unwrap();
        let p: usize = input.trim().parse().unwrap();
        gem[p] += 1;
    }

    let mut dp = vec![vec![-1; 501]; 30001];
    dp[d][250] = gem[d] as i32;

    for i in d + 1..=30000 {
        for j in 1..=499 {
            let jump = d + j - 250;
            if jump > 0 && i >= jump {
                let max_prev = cmp::max(
                    cmp::max(dp[i - jump][j - 1], dp[i - jump][j]),
                    dp[i - jump][j + 1],
                );
                if max_prev >= 0 {
                    dp[i][j] = max_prev + gem[i] as i32;
                }
            }
        }
    }

    let mut ans = 0;
    for i in d..=30000 {
        for j in 0..=500 {
            ans = cmp::max(ans, dp[i][j]);
        }
    }

    println!("{}", ans);
}

