            lcp[i][j] = if s[i] == s[j] { 1 + lcp[i + 1][j + 1] } else { 0 };
        }
    }

    for j in 0..n {
        for i in 0..j {
            let l = if j - i < lcp[i][j] { j - i } else { lcp[i][j] };
            if ll[j] < l {
                ll[j] = l;
            }
        }
    }

    for i in 0..=n {
        dp[i] = (i as i32) * a;
    }

    for i in 0..n {
        if dp[i + 1] > dp[i] + a {
            dp[i + 1] = dp[i] + a;
        }
        for j in i + 1..=n.min(i + ll[i]) {
            if dp[j] > dp[i] + b {
                dp[j] = dp[i] + b;
            }
        }
    }

