    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let first_line: Vec<&str> = lines.next().unwrap().split_whitespace().collect();
    let n: usize = first_line[0].parse().unwrap();
    let m: usize = first_line[1].parse().unwrap();
    let mut st: Vec<char> = lines.next().unwrap().chars().collect();
    st.push('\0'); // Sentinel character to avoid bounds checking

    let mut sum = 0;
    for i in 0..n {
        if st[i] == '.' && st[i + 1] == '.' {
            sum += 1;
        }
    }

    for _ in 0..m {
        let line: Vec<&str> = lines.next().unwrap().split_whitespace().collect();
        let x: usize = line[0].parse().unwrap();
        let c: char = line[1].chars().next().unwrap();
        let x = x - 1;

        if c == '.' && st[x] != '.' {
            if st[x.saturating_sub(1)] == '.' {
                sum += 1;
            }
            if st[x + 1] == '.' {
                sum += 1;
            }
        } else if c != '.' && st[x] == '.' {
            if st[x.saturating_sub(1)] == '.' {
                sum -= 1;
            }
            if st[x + 1] == '.' {
                sum -= 1;
            }
        }
        st[x] = c;
