use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let t: usize = lines.next().unwrap().parse().unwrap();
    let mut a_req = Vec::with_capacity(t);

    for _ in 0..t {
        let line = lines.next().unwrap();
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let h: i32 = parts.next().unwrap().parse().unwrap();
        let m: i32 = parts.next().unwrap().parse().unwrap();

        let mut c = Vec::with_capacity(n);

        for _ in 0..n {
            let line = lines.next().unwrap();
            let mut parts = line.split_whitespace();
            let a: i32 = parts.next().unwrap().parse().unwrap();
            let b: i32 = parts.next().unwrap().parse().unwrap();

            let diff = if a > h {
                ((a - h - 1) * 60) + 60 - m + b
            } else if a == h {
                if m > b {
                    24 * 60 - (m - b)
                } else {
                    b - m
                }
            } else {
                24 * 60 - ((h - a - 1) * 60) - (60 - b + m)
            };

            c.push(diff);
        }

        let e = c.iter().enumerate().min_by_key(|&(_, &val)| val).unwrap().0;
        a_req.push(c[e]);
    }

    for &time in &a_req {
        println!("{} {}", time / 60, time % 60);
    }
}

