	n = strlen(s);
	ff[0] = ff[1] = 1;
	for (i = 2; i <= n; i++)
		ff[i] = (ff[i - 1] + ff[i - 2]) % MD;
	for (i = 0; i < n; i++)
		if (s[i] == 'w' || s[i] == 'm') {
			printf("0\n");
			return 0;
		}
