	for (i = 0; i < n; )
		if (s[i] == 'u' || s[i] == 'n') {
			j = i + 1;
			while (j < n && s[j] == s[i])
				j++;
			ans = ans * ff[j - i] % MD;
			i = j;
		} else
			i++;
	printf("%lld\n", ans);
	return 0;
}

