			continue;
		}

		while(n)
		{
			if(n%10 < min)
				min = n%10;
			arr[k++] = n%10;
			n = n/10;
			count++;
		}
		ans = 0;
		int flag = 0;
		for(int j=0; j<count; j++)
		{
			if(j== count -1)
			{
				for(k = j-1; k>=0; k--)
				{
					if(arr[j] < arr[k])
					{
						flag = 1;
						ans = ans + arr[j];
						break;
					}
					else if(arr[j] > arr[k])
					{		
						flag = 1;
						ans = ans + arr[j] -1;
						break;
					}

				}	

			}	
			else
				ans = ans + 9;

		}
		if(flag == 0)
			ans = ans + arr[count-1];

		printf("%lld\n",ans);
	}
	return 0;
