fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let t: i64 = lines.next().unwrap().parse().unwrap();

    for _ in 0..t {
        let n: i64 = lines.next().unwrap().parse().unwrap();
        if n < 10 {
            println!("{}", n);
            continue;
        }

        let mut digits = Vec::new();
        let mut n = n;
        let mut min_digit = 10;
        while n > 0 {
            let digit = (n % 10) as i32;
            if digit < min_digit {
                min_digit = digit;
            }
            digits.push(digit);
            n /= 10;
        }

        let mut ans = 0;
        let mut flag = false;
        for (j, &digit) in digits.iter().enumerate().rev() {
            if j == 0 {
                if !flag {
                    ans += digit as i64;
                }
            } else {
                if digit < digits[j - 1] {
                    flag = true;
                    ans += digit as i64;
                } else if digit > digits[j - 1] {
                    flag = true;
                    ans += (digit - 1) as i64;
                } else {
                    ans += 9;
                }
            }
        }

        println!("{}", ans);
    }
}

