    let mut weight = vec![vec![0; n]; n];

    for (i, line) in lines.take(n).enumerate() {
        let row: Vec<i32> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        weight[i].extend_from_slice(&row);
    }

    for i in 0..n {
        if weight[i][i] != 0 {
            println!("NO");
            return;
        }
        for j in 0..i {
            if weight[i][j] != weight[j][i] || weight[i][j] == 0 {
                println!("NO");
                return;
            }
        }
    }

    for i in 0..n {
        let mut min = 0;
        for j in 0..n {
            if i != j && weight[i][j] < weight[i][min] {
                min = j;
            }
        }
        for j in 0..n {
            if (weight[i][j] - weight[min][j]).abs() != weight[i][min] {
                println!("NO");
                return;
            }
        }
    }

    println!("YES");
}

