const MAXN: usize = 5 * 100 * 100 * 10 + 6;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let first_line: Vec<&str> = lines.next().unwrap().split_whitespace().collect();
    let n: usize = first_line[0].parse().unwrap();
    let k: usize = first_line[1].parse().unwrap();
    let mut stripe: Vec<char> = lines.next().unwrap().chars().collect();
    stripe.resize(n, 'A'); // Ensure stripe has exactly n elements

    let mut d = vec![vec![MAXN + 243; 26]; n + 1];

    for i in 1..=n {
        for j in 0..k {
            for m in 0..k {
                if m == j { continue; }
                if d[i - 1][m] < d[i][j] {
                    d[i][j] = d[i - 1][m];
                }
            }
            if stripe[i - 1] as usize - 'A' as usize != j {
                d[i][j] += 1;
            }
        }
    }

    let mut ans = 0;
    for i in 0..k {
        if d[n][i] < d[n][ans] {
            ans = i;
        }
    }

    for i in (1..=n).rev() {
        for j in 0..k {
            if j != ans && d[i - 1][j] + (stripe[i - 1] as usize - 'A' as usize != ans) as usize == d[i][ans] {
                stripe[i - 1] = (ans as u8 + b'A') as char;
                ans = j;
                break;
            }
        }
    }

    println!("{}", d[n][ans]);
    println!("{}", stripe.iter().collect::<String>());
