        for i in 0..n {
            let mut sum = 0;
            for j in i..n {
                sum += a[j];
                if max[j - i] < sum {
                    max[j - i] = sum;
                }
            }
        }

        let mut ans = vec![0; n + 1];
        for i in 0..=n {
            for j in 0..n {
                let mut tmp = max[j];
                if j < i {
                    tmp += (j as i32 + 1) * x;
                } else {
                    tmp += i as i32 * x;
                }
                if tmp > ans[i] {
                    ans[i] = tmp;
                }
            }
        }

        print!("{}", ans[0]);
        for &val in &ans[1..] {
            print!(" {}", val);
        }
        println!();
    }
