fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let t: usize = lines.next().unwrap().parse().unwrap();
    let mut a = Vec::with_capacity(t);
    let mut b = Vec::with_capacity(t);
    let mut s = Vec::with_capacity(t);

    for _ in 0..t {
        let line = lines.next().unwrap();
        let mut parts = line.split_whitespace();
        let ai: usize = parts.next().unwrap().parse().unwrap();
        let bi: usize = parts.next().unwrap().parse().unwrap();
        a.push(ai);
        b.push(bi);

        let line = lines.next().unwrap();
        let si: Vec<i64> = line.split_whitespace()
                              .take(ai)
                              .map(|x| x.parse().unwrap())
                              .collect();
        s.push(si);
    }

    for m in 0..t {
        let am = a[m];
        let bm = b[m];
        let mut sm = s[m].clone();

        for i in 0..am {
            for k in (i + 1)..am {
                if sm[i] < sm[k] {
                    sm.swap(i, k);
                }
            }
        }

        let mut sum = 0;
        for i in 0..bm {
            sum += sm[bm + i] / sm[i];
        }

        for i in 0..(am - 2 * bm) {
            sum += sm[2 * bm + i];
        }

        println!("{}", sum);
    }
