        writeln!(io::stdout(), "impossible")?;
        return Ok(());
    }

    let mut diff_count = 0;
    for (a, b) in s.chars().zip(t.chars()) {
        if a != b {
            diff_count += 1;
        }
    }

    if diff_count % 2 != 0 {
        writeln!(io::stdout(), "impossible")?;
        return Ok(());
    }

    let mut an = String::with_capacity(s.len());
    let mut q = 0;
    for (a, b) in s.chars().zip(t.chars()) {
        if a != b {
            if q % 2 == 0 {
                an.push(a);
            } else {
                an.push(b);
            }
            q += 1;
        } else {
            an.push(a);
        }
    }

    writeln!(io::stdout(), "{}", an)?;
    Ok(())
}

