fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let s = input.trim();
    let (mut x, mut y) = (0, 0);

    for c in s.chars() {
        match c {
            'x' => x += 1,
            'y' => y += 1,
            _ => {}
        }
    }

    let mut stdout = io::stdout();
    if x > y {
        for _ in 0..(x - y) {
            stdout.write_all(b"x")?;
        }
    } else {
        for _ in 0..(y - x) {
            stdout.write_all(b"y")?;
        }
    }
    stdout.flush()?;
    Ok(())
}

