#define NCIF 10

int possible[NCIF][MAX0];
char *y_n[2] = { "NO\n", "YES\n" };

int main(){
  int t, n, d, i, j, tmp, out;

  for( d = 1 ; d < NCIF ; d++ ){
    for( i = 0 ; i < MAX0 ; i++ ){
      possible[d][i] = 0;
      tmp = i;
      while( tmp > 0 ){
        if( tmp % 10 == d )
          possible[d][i] = 1;
        tmp /= 10;
      }

      if( !possible[d][i] ){
        for( j = i / 2 ; j < i ; j++ ){
          if( possible[d][j] && possible[d][i - j] )
            possible[d][i] = 1;
        }
      }
    }
  }

  for( scanf("%d", &t) ; t-- ; ){
    for( scanf("%d%d", &n, &d) ; n-- ; ){
      scanf("%d", &tmp);
      if( tmp >= MAX0 ){
        out = 1;
      }else
        out = possible[d][tmp];
      fputs(y_n[out], stdout);
    }
  }
  return 0;
}

