use std::io::{self, Write};

const MAX0: usize = 100;
const NCIF: usize = 10;

fn main() {
    let mut possible = vec![vec![0; MAX0]; NCIF];
    let y_n = ["NO\n", "YES\n"];

    for d in 1..NCIF {
        for i in 0..MAX0 {
            possible[d][i] = if i.to_string().contains(&(d.to_string())) { 1 } else { 0 };
            if possible[d][i] == 0 {
                for j in (i / 2)..i {
                    if possible[d][j] == 1 && possible[d][i - j] == 1 {
                        possible[d][i] = 1;
                        break;
                    }
                }
            }
        }
    }

    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let mut t: i32 = input.trim().parse().unwrap();

    while t > 0 {
        input.clear();
        io::stdin().read_line(&mut input).unwrap();
        let mut parts = input.trim().split_whitespace();
        let n: i32 = parts.next().unwrap().parse().unwrap();
        let d: usize = parts.next().unwrap().parse().unwrap();

        for _ in 0..n {
            input.clear();
            io::stdin().read_line(&mut input).unwrap();
            let tmp: usize = input.trim().parse().unwrap();
            let out = if tmp >= MAX0 { 1 } else { possible[d][tmp] };
            print!("{}", y_n[out]);
            io::stdout().flush().unwrap();
        }
        t -= 1;
    }
}

