    std::io::stdin().read_line(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let m: usize = parts.next().unwrap().parse().unwrap();

    let mut clothes_prices = Vec::with_capacity(n);
    for _ in 0..n {
        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        clothes_prices.push(input.trim().parse::<i64>().unwrap());
    }

    let mut pairs = vec![vec![0; n + 1]; n + 1];
    for _ in 0..m {
        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        let mut parts = input.split_whitespace();
        let x: usize = parts.next().unwrap().parse().unwrap();
        let y: usize = parts.next().unwrap().parse().unwrap();
        pairs[x][y] = 1;
        pairs[y][x] = 1;
    }

    let mut min = i64::MAX;
    for i in 1..=n {
        for j in i + 1..=n {
            for k in j + 1..=n {
                if pairs[i][j] == 1 && pairs[j][k] == 1 && pairs[k][i] == 1 {
                    let sum = clothes_prices[i - 1] + clothes_prices[j - 1] + clothes_prices[k - 1];
                    if sum < min {
                        min = sum;
                    }
                }
            }
        }
    }

    if min != i64::MAX {
