use std::f64;

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let mut array: Vec<i64> = Vec::with_capacity(n);

        for _ in 0..n {
            let num: i64 = lines.next().unwrap().unwrap().parse().unwrap();
            array.push(num);
        }

        let mut max = -10000000000;
        let mut max_diff = 0;

        for &value in &array {
            if max < value {
                max = value;
            }

            if max - value > max_diff {
                max_diff = max - value;
            }
        }

        if max_diff == 0 {
            println!("0");
        } else {
            let exp = (max_diff as f64).log2().floor() as i32 + 1;
            println!("{}", exp);
        }
    }
}

