    int table[26];
    while (t-- > 0) {
        int n, k;
        scanf("%d%d", &n, &k);
        int s[n];
        char c = getchar();
        while (c < 'a' || c > 'z')
            c = getchar();
        for (int i = 0; i < n; i++) {
            s[i] = c - 'a';
            c = getchar();
        }
        int ans = 0;
        for (int i = 0; i < k / 2; i++) {
            for (int i = 0; i < 26; i++)
                table[i] = 0;
            for (int j = i; j < n; j += k) {
                table[s[j]]++;
            }
            for (int j = k - i - 1; j < n; j += k) {
                table[s[j]]++;
            }
            int max = 0;
            for (int j = 1; j < 26; j++) {
                if (table[j] > table[max]) max = j;
            }
            ans += n / k * 2 - table[max];
        }
        if (k % 2) {
            for (int i = 0; i < 26; i++)
                table[i] = 0;
            for (int j = k / 2; j < n; j += k) {
                table[s[j]]++;
            }
            int max = 0;
            for (int j = 1; j < 26; j++) {
                if (table[j] > table[max]) max = j;
            }
            ans += n / k - table[max];
        }
        printf("%d\n", ans);
    }
    return 0;
}

