    let mut ans = 0;
    let mut sum = 0;
    for len in 1..=n {
        let a: i64 = lines.next().unwrap().parse().unwrap();
        sum = (sum + a) % MD;
        let mut cnt = p2[n - len];
        if len + 2 <= n {
            cnt = (cnt + (n as i64 - 1 - len as i64) * p2[n - 2 - len]) % MD;
        }
        ans = (ans + sum * cnt) % MD;
    }
    println!("{}", ans);
}

