        let mut len = s.len() as u64;

        for l in 1..x {
            let curr = len - l as u64;
            for _ in 1..(s[l - 1] - b'0') {
                if len + curr > MOD {
                    len = (len + curr) % MOD;
                } else {
                    len += curr;
                }
            }
        }

        for l in x..=x {
            if len < l as u64 {
                len += MOD;
            }
            len += (len - l as u64) * (s[l - 1] - b'1') as u64;
            len %= MOD;
        }

        println!("{}", len);
    }
}

