fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    while let Some(line) = lines.next() {
        let nm: Vec<usize> = line.unwrap().split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        let n = nm[0];
        let m = nm[1];

        let mut str1 = vec![String::new(); m];
        let mut str2 = vec![String::new(); m];
        for i in 0..m {
            let line = lines.next().unwrap().unwrap();
            let mut parts = line.split_whitespace();
            str1[i] = parts.next().unwrap().to_string();
            str2[i] = parts.next().unwrap().to_string();
        }

        let mut str3 = vec![String::new(); n];
        for i in 0..n {
            str3[i] = lines.next().unwrap().unwrap();
            for j in 0..m {
                if str3[i] == str1[j] || str3[i] == str2[j] {
                    match str1[j].len().cmp(&str2[j].len()) {
                        Ordering::Less => {
                            str3[i] = str1[j].clone();
                            break;
                        }
                        Ordering::Greater => {
                            str3[i] = str2[j].clone();
                            break;
                        }
                        Ordering::Equal => {
                            if str1[j] < str2[j] {
                                str3[i] = str1[j].clone();
                                break;
                            } else {
                                str3[i] = str2[j].clone();
                                break;
                            }
                        }
                    }
                }
            }
        }

        println!("{}", str3.join(" "));
    }
}

