        Some(t) if (1..=10000).contains(&t) => t,
        _ => return,
    };

    let mut l = Vec::with_capacity(t);
    let mut r = Vec::with_capacity(t);
    let mut a = Vec::with_capacity(t);

    for _ in 0..t {
        let line = match lines.next().and_then(|line| line.ok()) {
            Some(line) => line,
            None => return,
        };
        let mut parts = line.split_whitespace();
        let l_i: i32 = match parts.next().and_then(|s| s.parse().ok()) {
            Some(l_i) if (1..=1_000_000_000).contains(&l_i) => l_i,
            _ => return,
        };
        let r_i: i32 = match parts.next().and_then(|s| s.parse().ok()) {
            Some(r_i) if (1..=1_000_000_000).contains(&r_i) => r_i,
            _ => return,
        };
        let a_i: i32 = match parts.next().and_then(|s| s.parse().ok()) {
            Some(a_i) if (1..=1_000_000_000).contains(&a_i) => a_i,
            _ => return,
        };
        if l_i > r_i {
            return;
        }
        l.push(l_i);
        r.push(r_i);
        a.push(a_i);
