fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    while let Some(Ok(line)) = lines.next() {
        let n: usize = line.parse().unwrap();
        let mut fri = vec![vec![0; n]; n];
        let mut prf = vec![0; n];
        let mut rank = vec![0; n];
        let mut order = vec![0; n];

        for i in 0..n {
            let line = lines.next().unwrap().unwrap();
            let nums: Vec<usize> = line.split_whitespace()
                .map(|x| x.parse().unwrap())
                .collect();
            fri[i] = nums.into_iter().map(|x| x - 1).collect();
        }

        let line = lines.next().unwrap().unwrap();
        let nums: Vec<usize> = line.split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect();
        for (i, &num) in nums.iter().enumerate() {
            prf[i] = num - 1;
            rank[prf[i]] = i;
        }

        for i in 0..n {
            let mut find = false;
            for j in 0..n {
                if find {
                    break;
                }
                let mut cur = None;
                for k in 0..n {
                    if find {
                        break;
                    }
                    if k != i {
                        if cur.is_none() || rank[k] < rank[cur.unwrap()] {
                            cur = Some(k);
                        }
                        if cur == Some(fri[i][j]) {
                            find = true;
                            order[i] = k;
                        }
                    }
                }
            }
        }

        let output = order.iter()
            .enumerate()
            .map(|(i, &x)| if i == n - 1 { format!("{}", x + 1) } else { format!("{} ", x + 1) })
            .collect::<String>();
        println!("{}", output);
    }
}

