            if mat[i][j] != mat[j][i] || (i != j && mat[i][j] == 0) {
                println!("NO");
                return;
            }
        }
    }

    for i in 0..n {
        if visited[i] {
            continue;
        }
        let min = mat[minind[i]][i];
        for j in 0..n {
            let diff = mat[i][j] - mat[minind[i]][j];
            if diff != min && diff + min != 0 {
                println!("NO");
                return;
            }
        }
        visited[i] = true;
        visited[minind[i]] = true;
    }
    println!("YES");
}

