use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0];
    let q = first_line[1];

    let mut position = vec![0; n + q];
    let mut actions: Vec<usize> = Vec::with_capacity(q);
    let mut location: Vec<usize> = Vec::with_capacity(n);
    let mut ans: Vec<usize> = vec![0; q];

    let positions_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    for (i, &pos) in positions_line.iter().enumerate() {
        position[q + i] = pos;
        location.push(q + i);
    }

    let actions_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    actions.extend(actions_line);

    for (k, &action) in actions.iter().enumerate() {
        for i in 0..n {
            if position[location[i]] == action {
                position[location[0] - 1] = action;
                position[location[i]] = 0;
                location[1..=i].rotate_right(1);
                location[0] -= 1;
                ans[k] = i + 1;
                break;
            }
        }
    }

    println!("{}", ans.iter().map(|a| a.to_string()).collect::<Vec<_>>().join(" "));
}

