fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let (n, m) = (first_line[0], first_line[1]);

    let mut feature = vec![vec![0; m]; n];
    for i in 0..n {
        let line = lines.next().unwrap();
        for (j, c) in line.chars().enumerate() {
            feature[i][j] = if c == 'B' { -1 } else { 1 };
        }
    }

    let mut field = vec![vec![0; m]; n];
    let mut ans = 0;

    for i in (0..n).rev() {
        for j in (0..m).rev() {
            let d = feature[i][j] - field[i][j];
            if d != 0 {
                ans += 1;
                for k in 0..=i {
                    for l in 0..=j {
                        field[k][l] += d;
                    }
                }
            }
        }
    }

    println!("{}", ans);
}

