    let mut ques = Vec::new();
    for &p in &primes {
        let mut fact = p;
        while fact * p <= n {
            fact *= p;
            cnt += 1;
            ques.push(fact);
        }
    }

    println!("{}", cnt);
    print!("{}", primes.iter().map(|&x| x.to_string()).collect::<Vec<_>>().join(" "));
