    let jump: Vec<usize> = lines
        .take(range)
        .map(|line| line.parse().unwrap())
        .collect();

    let mut visited = vec![false; range];
    let mut loc = 0;

    while loc < range {
        let res = match dir[loc] {
            '<' => {
                if loc < jump[loc] {
                    println!("FINITE");
                    return Ok(());
                }
                loc - jump[loc]
            }
            '>' => {
                if loc + jump[loc] >= range {
                    println!("FINITE");
                    return Ok(());
                }
                loc + jump[loc]
            }
            _ => unreachable!(),
        };

        if visited[res] {
            println!("INFINITE");
            return Ok(());
        }

        visited[res] = true;
        loc = res;
    }

    Ok(())
}

