fn main() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let mut t: i32 = input.trim().parse().unwrap();

    while t != 0 {
        input.clear();
        io::stdin().read_line(&mut input).unwrap();
        let s = input.trim();
        let l = s.len();

        if l == 2 {
            print!("{}", s);
        } else {
            print!("{}", s.chars().nth(0).unwrap());
            let mut chars = s.chars().enumerate().peekable();
            chars.next(); // Skip the first character

            while let Some((i, c)) = chars.next() {
                if i >= 2 && i <= l - 2 {
                    if let Some(&(_, next_c)) = chars.peek() {
                        if c == next_c {
                            print!("{}", c);
                            chars.next(); // Skip the next character as well
                        }
                    }
                }
            }
            print!("{}", s.chars().nth(l - 1).unwrap());
        }

        t -= 1;
        if t != 0 {
            println!();
        } else {
            io::stdout().flush().unwrap();
        }
    }
}

