			{
				visited[minava] = 1;
			}
			else
			{
				target = i; 
			}
		}
		if (target == -1)
		{
			printf("OPTIMAL\n"); 
		}
		else
		{
			for (int i = 1; i <= n; ++i)
			{
				if (!visited[i])
				{
					addtarget = i; 
					break; 
				}
			}
