            let mut min_ava = n + 1;
            for _ in 0..k {
                let tmp: usize = lines.next().unwrap().parse().unwrap();
                if tmp < min_ava && !visited[tmp] {
                    min_ava = tmp;
                }
            }
            if min_ava <= n {
                visited[min_ava] = true;
            } else {
                target = Some(i);
            }
        }

        if let Some(t) = target {
            for i in 1..=n {
                if !visited[i] {
                    add_target = Some(i);
                    break;
                }
            }
            println!("IMPROVE\n{} {}", t, add_target.unwrap());
        } else {
            println!("OPTIMAL");
        }
    }
}

