    let mut b = vec![0; n + 1];

    let a_line: Vec<i32> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    for (i, &value) in a_line.iter().enumerate() {
        a[i + 1] = value;
    }

    for _ in 0..m {
        let lr: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let l = lr[0];
        let r = lr[1];

        let count: i32 = a[l..=r].iter().sum();
        if count > 0 {
            for j in l..=r {
                b[j] += 1;
            }
        }
    }

    let result: i32 = a.iter().zip(b.iter()).skip(1)
        .map(|(&ai, &bi)| ai * bi).sum();

    println!("{}", result);
