        let n: usize = parts.next().unwrap().parse().unwrap();
        let m: usize = parts.next().unwrap().parse().unwrap();

        let mut mark = vec![vec![' '; m + 1]; n + 1];
        let mut suc = vec![0; n + 1];
        let mut count = 0;

        for i in 1..=n {
            if let Some(row) = lines.next() {
