                    mark[i][j + 1] = c;
                }
            }
        }

        for i in 1..=m {
            let mut max = -1;
            for j in 1..=n {
                let val = mark[j][i] as i32 - '0' as i32;
                if max < val {
                    max = val;
                }
            }
            for j in 1..=n {
                if mark[j][i] as i32 - '0' as i32 == max {
                    suc[j] = 1;
                }
            }
        }

        for i in 1..=n {
            if suc[i] == 1 {
                count += 1;
            }
        }

        println!("{}", count);
