                        for g in j + 1..=m {
                            if (j as i32 - x[j]) == (g as i32 - x[g]) {
                                x.swap(j, g);
                                swapped = true;
                            }
                        }
                    }
                    if !swapped {
                        break;
                    }
                }

                for j in 1..=m {
                    print!("{} ", x[j]);
                }
                println!();
            }
        }
    }
}

