fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();

    for _ in 0..t {
        let mut s: Vec<char> = lines.next().unwrap().unwrap().chars().collect();
        let mut cnt = 0;

        while !is_done(&s) {
            let mut i = 0;
            while i < s.len() - 1 {
                if s[i] != s[i + 1] {
                    s.drain(i..=i + 1);
                    cnt += 1;
                    if i > 0 {
                        i -= 1;
                    }
                } else {
                    i += 1;
                }
            }
        }

        if cnt % 2 == 0 {
            println!("NET");
        } else {
            println!("DA");
        }
    }
}

fn is_done(s: &[char]) -> bool {
    if s.len() <= 1 {
        return true;
    }
    s.windows(2).all(|w| w[0] == w[1])
}

