fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let a = lines.next().unwrap().unwrap();
    let b = lines.next().unwrap().unwrap();

    if a.len() != b.len() {
        println!("NO");
        return;
    }

    let mut diff_indices = Vec::new();

    for (i, (char_a, char_b)) in a.chars().zip(b.chars()).enumerate() {
        if char_a != char_b {
            diff_indices.push(i);
            if diff_indices.len() > 2 {
                println!("NO");
                return;
            }
        }
    }

    match diff_indices.len() {
        0 => println!("YES"),
        2 => {
            let mut a_chars: Vec<char> = a.chars().collect();
            a_chars.swap(diff_indices[0], diff_indices[1]);
            if a_chars.iter().collect::<String>() == b {
                println!("YES");
            } else {
                println!("NO");
            }
        }
        _ => println!("NO"),
    }
}

