#define MAX(A, B) (A > B ? A : B)

int widths[101], cum_vals[101][105], max_dmg[101][101];
int dp[101][10001];
int main() {
	int n, m, i, j, k;

	scanf("%d %d", &n, &m);
	for (i = 0; i < n; i++) {
		scanf("%d", widths+i);
		cum_vals[i][0] = 0;
		for (j = 1; j <= widths[i]; j++) {
			scanf("%d", &cum_vals[i][j]);
			cum_vals[i][j] += cum_vals[i][j-1];
			max_dmg[i][j] = 0;
		}
	}
	for (i = 0; i < n; i++) {
		for (j = 0; j <= widths[i]; j++) {
			for (k = 0; k <= j; k++) {
				max_dmg[i][j] = MAX(max_dmg[i][j], cum_vals[i][k] + cum_vals[i][widths[i]] - cum_vals[i][widths[i]-j+k]);
			}
		}
	}
	for (i = 0; i < n; i++) {
		for (j = 0; j <= m; j++) {
			for (k = 0; k <= widths[i] && k+j <= m; k++) {
				dp[i+1][j+k] = MAX(dp[i+1][j+k], dp[i][j] + max_dmg[i][k]);
			}
		}
	}
	printf("%d\n", dp[n][m]);

	return 0;
}

