        let numbers: Vec<i32> = input_line.split_whitespace()
                                         .map(|s| s.parse().unwrap())
                                         .collect();
        arr[..n].copy_from_slice(&numbers);

        let mut count = 0;
        for i in 0..n {
            for j in (arr[i] - i as i32 - 2..n as i32).step_by(arr[i] as usize) {
                if i == j as usize || j < 0 {
                    continue;
                } else if arr[i] * arr[j as usize] == i as i32 + j + 2 {
                    count += 1;
                }
            }
        }
        println!("{}", count / 2);
    }
}

