use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();

    let mut a = vec![vec![0; n]; n];
    let mut v1 = vec![0; 2 * n - 1];
    let mut v2 = vec![0; 2 * n - 1];
    let mut x = [0; 2];
    let mut y = [0; 2];
    let mut p = [0; 2];

    for (i, line) in lines.enumerate().take(n) {
        let row: Vec<i64> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        for (j, &value) in row.iter().enumerate().take(n) {
            a[i][j] = value;
            v1[i + j] += value;
            v2[i + n - 1 - j] += value;
        }
    }

    for i in 0..n {
        for j in 0..n {
            let t = (i + j) & 1;
            let r = v1[i + j] - a[i][j] + v2[i + n - 1 - j];
            if r > p[t] {
                x[t] = i as i64 + 1;
                y[t] = j as i64 + 1;
                p[t] = r;
            }
        }
    }

    println!("{}", p[0] + p[1]);
    println!("{} {}", x[0], y[0]);
    println!("{} {}", x[1], y[1]);
}

