    let n: usize = input.trim().parse().expect("Please enter a valid number");

    let mut a: Vec<i32> = Vec::with_capacity(n);
    for _ in 0..n {
        input.clear();
        io::stdin().read_line(&mut input)?;
        a.push(input.trim().parse().expect("Please enter a valid number"));
    }

    let mut i = 0;
    let mut c = 'R';
    let mut stdout = io::stdout();

    if a[i] != 0 {
        stdout.write_all(b"P")?;
        a[i] -= 1;
    }
    i += 1;

    while i < n {
        if c == 'L' && a[i] == 0 && i + 1 < n && a[i + 1] == 0 {
            break;
        }
        stdout.write_all(c.to_string().as_bytes())?;
        if c == 'R' {
            if a[i] != 0 {
                stdout.write_all(b"P")?;
                a[i] -= 1;
            }
            if a[i - 1] == 0 && i + 1 < n {
                c = 'R';
                i += 1;
            } else {
                c = 'L';
                i -= 1;
            }
        } else {
            if a[i] != 0 {
                stdout.write_all(b"P")?;
                a[i] -= 1;
            }
            c = 'R';
            i += 1;
        }
    }

    stdout.flush()?;
    Ok(())
}

