{
	int i, j, k;
	int N;
	scanf("%d", &N);
	for (i = 1; i <= N; ++i){
		scanf("%d", &arr[i]);
		++chk[arr[i]];
		if (chk[arr[i]] == 3){
			flag = 1;
		}
		if (arr[i] > max){
			max = arr[i];
		}
		if (arr[i] < min){
			min = arr[i];
		}
	}
	if (flag == 1){
		printf("NO");
		return 0;
	}
	else{
		printf("YES\n");
		for (i = 0; i <= max; ++i){
			if (chk[i] >= 1){
				--chk[i];
				ans[++cnt] = i;
			}
		}
		printf("%d\n", cnt);
		for (i = 1; i <= cnt; ++i){
			printf("%d ", ans[i]);
		}
		cnt = 0;
		memset(ans, 0, sizeof(ans));
		printf("\n");
		for (i = max; i >= min; --i){
			if (chk[i] >= 1){
				--chk[i];
				ans[++cnt] = i;
			}
		}
		printf("%d\n", cnt);
		for (i = 1; i <= cnt; ++i){
			printf("%d ", ans[i]);
