        for (j = 0; j <= 2500; j++){
            for (k = 0; k < 26; k++){
                if (j - k >= 0){
                    dp[i][j] += dp[i - 1][j - k];
                    if (dp[i][j] >= MOD){
                        dp[i][j] -= MOD;
                    }
                }
            }
        }
    }

