    let mut v = vec![0; m];

    for _ in 0..n {
        let line = lines.next().unwrap();
        for (j, ch) in line.chars().enumerate() {
            match ch {
                'U' if j % 2 == 0 => v[j] += 1,
                'L' if j >= _k => v[j - _k] += 1,
                'R' if j + _k < m => v[j + _k] += 1,
                _ => {}
            }
        }
    }

    for count in v {
        print!("{} ", count);
    }
}

