    for (i, c) in str_input.chars().enumerate() {
        if c == '(' {
            stack.push(i);
        } else if let Some(open_index) = stack.pop() {
            pairs.push((open_index, i));
        }
    }

    let m = (n - k) / 2;
    for &(a, b) in &pairs[..m] {
        flag[a] = true;
        flag[b] = true;
    }

