            .map(|s| s.parse().unwrap()).collect();
        let second_line: Vec<i32> = lines.next().unwrap().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();

        let (b, p, f) = (first_line[0], first_line[1], first_line[2]);
        let (h, c) = (second_line[0], second_line[1]);

        let result = if h > c {
            if 2 * p <= b {
                if (b - 2 * p) >= 2 * f {
                    h * p + f * c
                } else {
                    h * p + ((b - 2 * p) / 2) * c
                }
            } else {
                (b / 2) * h
            }
        } else {
            if 2 * f <= b {
                if (b - 2 * f) >= 2 * p {
                    c * f + h * p
                } else {
                    c * f + ((b - 2 * f) / 2) * h
                }
            } else {
                (b / 2) * c
            }
        };

        results.push(result);
    }

