const int N = 131071;
const int MOD = 1000000007;

int f[262144];

int main()
{
    int t, k;
    scanf("%d%d", &t, &k);
    for (int i = 0; i < k; i++)
    {
        f[i + N] = 1;
    }
    for (int i = k; i <= 100000; i++)
    {
        f[i + N] = (f[i-1+N] + f[i-k+N]) % MOD;
    }
    for (int i = N-1; i >= 0; i--)
    {
        f[i] = (f[2 * i + 1] + f[2 * i + 2]) % MOD;
    }
    for (int i = 0; i < t; i++)
    {
        int a, b, ans = 0;
        scanf("%d%d", &a, &b);
        a += N;
        b += N;
        while (a < b)
        {
            if ((a & 1) == 0)
            {
                ans += f[a];
                ans %= MOD;
                a++;
            }
            if ((b & 1) == 1)
            {
                ans += f[b];
                ans %= MOD;
                b--;
            }
            a = (a-1) / 2;
            b = (b-1) / 2;
        }
        if (a == b)
        {
            ans += f[a];
            ans %= MOD;
        }
        printf("%d\n", ans);
    }
    return 0;
}

