    let mut dimensions = first_line.split_whitespace();
    let n: usize = dimensions.next().unwrap().parse().unwrap();
    let m: usize = dimensions.next().unwrap().parse().unwrap();

    let mut grid = vec![vec![' '; m + 2]; n + 2];
    let mut count = 0;
    let mut flag = false;
    let mut top = 0;
    let mut bottom = 0;
    let mut left = 0;
    let mut right = 0;

