        let chars: Vec<char> = line.chars().collect();
        for (j, &c) in chars.iter().enumerate().take(m) {
            grid[i + 1][j + 1] = c;
            if c == 'B' {
                count += 1;
                if !flag {
                    top = i + 1;
                    bottom = i + 1;
                    left = j + 1;
                    right = j + 1;
                    flag = true;
                }
                if j + 1 < left {
                    left = j + 1;
                }
                if j + 1 > right {
                    right = j + 1;
                }
                if i + 1 < top {
                    top = i + 1;
                }
                if i + 1 > bottom {
                    bottom = i + 1;
                }
            }
        }
