        if !is_palindrome(segment) {
            flag = true;
            break;
        }
    }

    if flag {
        writeln!(io::stdout(), "NO")?;
    } else {
        writeln!(io::stdout(), "YES")?;
    }

    Ok(())
}

fn is_palindrome(s: &str) -> bool {
    s.chars().eq(s.chars().rev())
}

