    if let Some(Ok(n_str)) = lines.next() {
        let mut n: i32 = n_str.parse().unwrap();
        while n > 0 {
            if let Some(Ok(m_str)) = lines.next() {
                let m: usize = m_str.parse().unwrap();
                let mut a: Vec<i32> = Vec::with_capacity(m);

                for _ in 0..m {
                    if let Some(Ok(num_str)) = lines.next() {
                        a.push(num_str.parse().unwrap());
                    }
                }

                for i in 1..m {
                    let temp = a[i];
                    let mut j = i as isize - 1;
                    while j >= 0 && temp < a[j as usize] {
                        a[(j + 1) as usize] = a[j as usize];
                        j -= 1;
                    }
                    a[(j + 1) as usize] = temp;
                }

                let mut k = 0;
                for i in 0..m - 1 {
                    if a[i + 1] - a[i] < 2 {
                        k += 1;
                    }
                }

                if k == 0 {
                    println!("1");
                } else {
                    println!("2");
                }
            }
            n -= 1;
        }
    }
}

