            b[i - 1] += 1;
        }
    }

    let mut ans: i64 = 0;
    let mut last = -1;
    for i in (1..N).rev() {
        if cnt[i] == 0 {
            continue;
        }
        if last != -1 {
            cnt[i] -= 1;
            ans += (last as i64) * (i as i64);
            last = -1;
        }
        ans += (cnt[i] as i64 / 2) * (i as i64) * (i as i64);
        if cnt[i] % 2 == 1 {
            last = i as i32;
        }
    }

    println!("{}", ans);
}

