            for j in 1..=n {
                if mark[j][i] as i32 - '0' as i32 == max {
                    suc[j] = 1;
                }
            }
        }

        for i in 1..=n {
            if suc[i] == 1 {
                count += 1;
            }
        }

        println!("{}", count);
