		for (i = 0; i < n; i++) {
			if (i + 1 < n) {
				int d = i % 2 == 0 ? (aa[i] - aa[i + 1]) * 2 : (aa[i + 1] - aa[i]) * 2;

				if (sum == d && aa[i + 1] - x >= 0 && aa[i] - aa[i + 1] + x >= 0)
					i_ = i;
			}
			if ((x = aa[i] - x) < 0)
				break;
		}
		if (sum != 0 && i_ == -1) {
			printf("NO\n");
			continue;
		}
		if (sum != 0)
			tmp = aa[i_], aa[i_] = aa[i_ + 1], aa[i_ + 1] = tmp;
		yes = 1;
		x = 0;
		for (i = 0; i < n; i++)
			if ((x = aa[i] - x) < 0) {
				yes = 0;
				break;
			}
		printf(yes ? "YES\n" : "NO\n");
	}
	return 0;
}

