use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut t: i32 = lines.next().unwrap().parse().unwrap();

    while t > 0 {
        let n: usize = lines.next().unwrap().parse().unwrap();
        let mut aa: Vec<i32> = lines.next().unwrap().split_whitespace()
            .take(n)
            .map(|s| s.parse().unwrap())
            .collect();

        let sum: i64 = aa.iter().enumerate()
            .map(|(i, &val)| if i % 2 == 0 { val as i64 } else { -(val as i64) })
            .sum();

        let mut i_ = None;
        let mut x = 0;
        for (i, &val) in aa.iter().enumerate() {
            if i + 1 < n {
                let d = if i % 2 == 0 {
                    (val - aa[i + 1]) * 2
                } else {
                    (aa[i + 1] - val) * 2
                };

                if sum == d as i64 && aa[i + 1] - x >= 0 && val - aa[i + 1] + x >= 0 {
                    i_ = Some(i);
                }
            }
            x = val - x;
            if x < 0 {
                break;
            }
        }

        if sum != 0 && i_.is_none() {
            println!("NO");
            t -= 1;
            continue;
        }

        if let Some(i) = i_ {
            aa.swap(i, i + 1);
        }

        let mut yes = true;
        x = 0;
        for &val in &aa {
            x = val - x;
            if x < 0 {
                yes = false;
                break;
            }
        }

        println!("{}", if yes { "YES" } else { "NO" });
        t -= 1;
    }
}

