                    let t2 = n / 3 - c[j];
                    if t2 > 0 {
                        if t2 >= t1 {
                            c[i] -= t1;
                            c[j] += t1;
                            min += t1 * arr[i][j];
                        } else {
                            c[i] -= t2;
                            c[j] += t2;
