    let n: usize = parts.next().unwrap().parse().unwrap();
    let l: i32 = parts.next().unwrap().parse().unwrap();
    let a: i32 = parts.next().unwrap().parse().unwrap();

    if n == 0 {
        println!("{}", l / a);
        return;
    }

    let mut cus_t = Vec::with_capacity(n);
    let mut cus_d = Vec::with_capacity(n);

    for _ in 0..n {
