use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n: usize = lines.next().unwrap().unwrap().parse().unwrap();

    let mut state = [2; 10];

    for _ in 0..n {
        let line = lines.next().unwrap().unwrap();
        let mut parts = line.split_whitespace();
        let ch = parts.next().unwrap().chars().next().unwrap();
        let tmp: u16 = parts.next().unwrap().parse().unwrap();

        match ch {
            '|' => {
                for (j, bit) in state.iter_mut().enumerate() {
                    if tmp & (1 << j) != 0 {
                        *bit = 1;
                    }
                }
            }
            '&' => {
                for (j, bit) in state.iter_mut().enumerate() {
                    if tmp & (1 << j) == 0 {
                        *bit = 0;
                    }
                }
            }
            '^' => {
                for (j, bit) in state.iter_mut().enumerate() {
                    if tmp & (1 << j) != 0 {
                        *bit ^= 1;
                    }
                }
            }
            _ => {}
        }
    }

    let mut orv = 0;
    let mut xorv = 0;
    let mut andv = 1023;

    for (i, &bit) in state.iter().enumerate() {
        match bit {
            0 => andv -= 1 << i,
            1 => orv += 1 << i,
            3 => xorv += 1 << i,
            _ => {}
        }
    }

    println!("3\n| {}\n& {}\n^ {}", orv, andv, xorv);
}

