#define N	5000

int main() {
	static char s[N + 1];
	static int dp[N + 1], lcp[N + 1][N + 1], ll[N];
	int n, a, b, i, j;

	scanf("%d%d%d%s", &n, &a, &b, s);
	for (i = n - 1; i >= 0; i--)
		for (j = n - 1; j >= 0; j--)
			lcp[i][j] = s[i] == s[j] ? 1 + lcp[i + 1][j + 1] : 0;
	for (j = 0; j < n; j++)
		for (i = 0; i < j; i++) {
			int l = j - i < lcp[i][j] ? j - i : lcp[i][j];

			if (ll[j] < l)
				ll[j] = l;
		}
	for (i = 0; i <= n; i++)
		dp[i] = i * a;
	for (i = 0; i < n; i++) {
		if (dp[i + 1] > dp[i] + a)
			dp[i + 1] = dp[i] + a;
		for (j = i + 1; j <= n && j <= i + ll[i]; j++)
			if (dp[j] > dp[i] + b)
				dp[j] = dp[i] + b;
	}
	printf("%d\n", dp[n]);
	return 0;
}

