    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let t: usize = lines.next().unwrap().parse().unwrap();
    let mut results = Vec::with_capacity(t);

    for _ in 0..t {
        let first_line: Vec<usize> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let (n, h, m) = (first_line[0], first_line[1], first_line[2]);

        let mut arr = Vec::with_capacity(n);
        for _ in 0..n {
            let time: Vec<usize> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
            let (h1, m1) = (time[0], time[1]);

            let diff = if h1 > h {
                (h1 - h) * 60
            } else if h1 == h {
                if m1 >= m {
                    0
                } else {
                    24 * 60
                }
            } else {
                (24 - h + h1) * 60
            } + (m1 - m);

            arr.push(diff);
        }

        arr.sort_unstable();
        results.push((arr[0] / 60, arr[0] % 60));
    }

    for (hour, min) in results {
        println!("{} {}", hour, min);
    }
