                ans = (ans + f[a]) % MOD;
                a += 1;
            }
            if b % 2 == 1 {
                ans = (ans + f[b]) % MOD;
                b -= 1;
            }
            a = (a - 1) / 2;
            b = (b - 1) / 2;
        }
        if a == b {
            ans = (ans + f[a]) % MOD;
        }
        println!("{}", ans);
    }
}

