use std::io::{self, Read};

const MOD: u64 = 1_000_000_007;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut dp = vec![vec![vec![0; 1001]; 55]; 1001];
    let mut a = vec![vec![0; 1001]; 101];
    let mut fact = vec![0; 101];
    let mut binom = vec![vec![0; 2001]; 2001];

    for i in 0..=1000 {
        dp[i][0][0] = 1;
    }
    for add in 1..=1000 {
        for len in 1..=52 {
            for sum in 1..=1000 {
                dp[add][len][sum] = dp[add - 1][len][sum];
                if sum >= add {
                    dp[add][len][sum] = (dp[add][len][sum] + dp[add - 1][len - 1][sum - add]) % MOD;
                }
            }
        }
    }
    for len in 1..=52 {
        for sum in 1..=1000 {
            a[len][sum] = dp[1000][len][sum];
        }
    }

    fact[0] = 1;
    for i in 1..=100 {
        fact[i] = (fact[i - 1] * i as u64) % MOD;
    }
    for i in 0..=2000 {
        binom[i][0] = 1;
    }
    for i in 1..=2000 {
        for j in 1..=i {
            binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % MOD;
        }
    }

    let t: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..t {
        let nk: Vec<usize> = lines.next().unwrap().split_whitespace().map(|x| x.parse().unwrap()).collect();
        let n = nk[0];
        let k = nk[1];
        let mut sol = 0;
        if k >= 51 {
            println!("0");
        } else {
            for i in 1..=n {
                sol = (sol + (a[k][i] as u64 * fact[k] % MOD * binom[n - i + k][k] % MOD)) % MOD;
            }
            println!("{}", sol);
        }
    }
