            if(i != j && Mat[i][j] & 1)
            {
                break;
            }
        }
        if(j == N)
        {
            for(j = 0; j < N; ++j)
            {
                if(Mat[j][i] > 1)
                {
                    break;
                }
            }
            if(j == N)
            {
                Ans[Cnt++] = i + 1;
            }
        }
    }
