    let mut ps = vec![0; n + 1];
    let mut rs = vec![0; n + 1];
    let mut maxinc = 0;

    for i in 1..=n {
        ps[i] = ps[i - 1] + a[i - 1] as i64 * b[i - 1] as i64;
        for j in (2..=i).rev() {
            rs[j] = rs[j - 2]
                + a[i - j] as i64 * b[i - 1] as i64
                + a[i - 1] as i64 * b[i - j] as i64;

            let inc = rs[j] - (ps[i] - ps[i - j]);
            if inc > maxinc {
                maxinc = inc;
            }
        }
        rs[1] = a[i - 1] as i64 * b[i - 1] as i64;
    }

    println!("{}", ps[n] + maxinc);
}

