#include <stdio.h>
#include <string.h>

#define MD	1000000007

int main() {
	static int dp[1025], dq[1025];
	int n, k, x, a, a_, sum;

	scanf("%d%d", &n, &k);
	dp[0] = 1;
	sum = 0;
	while (n-- > 0) {
		scanf("%d", &x);
		memset(dq, 0, sizeof dq);
		for (a = 0; a < 1 << (k - 1); a++) {
			if (x == 2 || x == 0)
				dq[a + 1] = (dq[a + 1] + dp[a]) % MD;
			if (x == 4 || x == 0) {
				a_ = a % 2 == 0 ? a + 2 : 2;
				dq[a_] = (dq[a_] + dp[a]) % MD;
			}
		}
		memcpy(dp, dq, sizeof dq);
		if (x == 0)
			sum = sum * 2 % MD;
		sum = (sum + dp[1 << (k - 1)]) % MD;
	}
	printf("%d\n", sum);
	return 0;
}

