const N: usize = 1_000_000;

fn main() {
    let mut composite = vec![false; 2 * N + 1];

    for n in 2..=2 * N {
        if composite[n] {
            continue;
        }

        for m in (n + n..=2 * N).step_by(n) {
            composite[m] = true;
        }
    }

    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
    let mut a: Vec<i32> = Vec::with_capacity(n);
    let mut cnt = 0;

    for _ in 0..n {
        let num: i32 = lines.next().unwrap().unwrap().parse().unwrap();
        a.push(num);
        if num == 1 {
            cnt += 1;
        }
    }

    if cnt > 1 {
        let mut b = 0;
        for &num in &a {
            if num > 1 && !composite[(num + 1) as usize] {
                b = num;
            }
        }
        println!("{}", if b == 0 { cnt } else { cnt + 1 });
        print!("1");
        for _ in 1..cnt {
            print!(" 1");
        }
        if b > 0 {
            print!(" {}", b);
        }
        println!();
    } else {
        for (i, &num1) in a.iter().enumerate() {
            for &num2 in &a[i + 1..] {
                if !composite[(num1 + num2) as usize] {
                    println!("2");
                    println!("{} {}", num1, num2);
                    return;
                }
            }
        }
        println!("1");
        println!("{}", a[0]);
    }
}

