        io::stdin().read_line(&mut input).expect("Failed to read line");
        let values: Vec<i32> = input.split_whitespace()
            .map(|s| s.parse().expect("Please type a number!"))
            .collect();

        if values.len() != 3 {
            writeln!(io::stdout(), "error").expect("Failed to write");
            return;
        }

        for (i, &value) in values.iter().enumerate() {
            if value < -100 || value > 100 {
                writeln!(io::stdout(), "error").expect("Failed to write");
                return;
            }
            row[i] = value;
        }
    }

    for (i, sum) in total.iter_mut().enumerate() {
        *sum = force.iter().map(|row| row[i]).sum();
    }

    if total == [0, 0, 0] {
        writeln!(io::stdout(), "YES").expect("Failed to write");
    } else {
