fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let mut arr: Vec<i32> = Vec::with_capacity(2 * n);
        let mut evens: Vec<usize> = Vec::with_capacity(2 * n);
        let mut odds: Vec<usize> = Vec::with_capacity(2 * n);

        for (i, line) in lines.by_ref().take(2 * n).enumerate() {
            let num: i32 = line.unwrap().parse().unwrap();
            arr.push(num);
            if num % 2 == 0 {
                evens.push(i + 1);
            } else {
                odds.push(i + 1);
            }
        }

        let mut e = evens.len();
        let mut o = odds.len();

        if o % 2 == 1 && e % 2 == 1 {
            o -= 1;
            e -= 1;
        } else if o % 2 == 0 && e % 2 == 0 {
            if o != 0 {
                o -= 2;
            } else {
