char s[N + 1];
int a[N + 1];

int main(){

	int len, i, j, mx, ans;
	scanf("%s", s);
	len = strlen(s);

	a[0] = 0;
	a[1] = s[0] == '(' && s[1] == ')' ? 2 : 0;
	for(i = 2; i < len; i++){
		if (s[i] == '('){
			a[i] = 0;
		}
		else {
			if (s[i - 1] == '('){
				a[i] = a[i - 2] + 2;
			}
			else {
				j = i - a[i - 1] - 1;
				if (j - 1 < 0 || a[i - 1] == 0 || s[j] == ')'){
					a[i] = 0;
				}
				else {
					a[i] = a[i - 1] + a[j - 1] + 2;
				}

				if (j - 1 < 0 && s[j] == '('){
					a[i] = 2 + a[i - 1];	
				}
			}
		}
	}

	mx = 0, ans = 1;
	for(i = 0; i < len; i++){
		if (mx < a[i]){
			mx = a[i];
			ans = 1;
		}
		else if (mx == a[i]){
			++ans;
		}
	}

	if (mx == 0){
		printf("0 1\n");
	}
	else {
		printf("%d %d\n", mx, ans);
	}

	return 0;
}

